#include <atomic>
#include <cstddef>
#include <memory>

template <class T, std::size_t N>   // N must be a power of two
class SpscRing {
    static_assert((N & (N - 1)) == 0, "capacity must be a power of two");
    T buf_[N];
    alignas(64) std::atomic<unsigned> head_{0};   // producer-owned, own cache line
    alignas(64) std::atomic<unsigned> tail_{0};   // consumer-owned, own cache line
public:
    // push: write the item, THEN publish the head with release.
    bool push(T v) {
        const auto h = head_.load(std::memory_order_relaxed);
        const auto t = tail_.load(std::memory_order_acquire);
        if (h - t == N) return false;                   // full: policy is 'refuse'
        buf_[h & (N - 1)] = v;
        head_.store(h + 1, std::memory_order_release);  // release: item before head
        return true;
    }
    bool pop(T& out) {
        const auto t = tail_.load(std::memory_order_relaxed);
        const auto h = head_.load(std::memory_order_acquire);
        if (h == t) return false;                       // empty
        out = buf_[t & (N - 1)];
        tail_.store(t + 1, std::memory_order_relaxed);
        return true;
    }
};
// boost::circular_buffer is the general (dynamic, optionally locking) alternative.
